vec3 grid(vec2 uv, float size, float stroke){  vec3 f;vec2 grid = tile(uv, size);f = vec3( box( (grid), vec2(stroke) ));return f;}

vec3 ggrid(vec2 UV, vec2 LineSize,vec2 GridSize)
{
    vec2 p= fract(UV*LineSize+GridSize/2.0);
    return vec3(step(GridSize.x, p.x)*step(GridSize.y, p.y));
}

float circle(vec2 st, float radius){
    vec2 pos = vec2(0.5)-st;
    radius *= 0.75;
    return 1.-smoothstep(radius-(radius*0.05),radius+(radius*0.05),dot(pos,pos)*3.14);
}

